    k = row.get('line_key')
    if k != None:
        left_totals[k] = left_totals.get(k, 0) + (row.get('output_amount', 0) or 0)
for row in right_rows:
    k = row.get('line_key')
    if k != None:
        right_totals[k] = right_totals.get(k, 0) + (row.get('rework_units', 0) or 0)
